CREATE TABLE public.quiz_questions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), quiz_id UUID NOT NULL REFERENCES public.quizzes(id) ON DELETE CASCADE, question TEXT NOT NULL, options JSONB NOT NULL DEFAULT '[]'::jsonb, correct_answer INTEGER NOT NULL DEFAULT 0, explanation TEXT, points INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); ALTER TABLE public.quiz_questions ENABLE ROW LEVEL SECURITY; CREATE POLICY "Public read questions" ON public.quiz_questions FOR SELECT USING (true); CREATE POLICY "Admin manage questions" ON public.quiz_questions FOR ALL USING (has_role(auth.uid(), 'admin'::app_role)); CREATE INDEX idx_quiz_questions_quiz ON public.quiz_questions(quiz_id, sort_order);